DO $$ DECLARE n int; step jsonb; BEGIN
  SELECT count(*) INTO n FROM agent_definitions WHERE type='content-feed-orchestrator' AND is_active AND COALESCE(is_snapshot,false)=false AND deleted_at IS NULL;
  IF n <> 1 THEN RAISE EXCEPTION '540: expected exactly 1 live row, found %', n; END IF;
  SELECT default_config #> ARRAY['workflow','steps','complete'] INTO step FROM agent_definitions WHERE type='content-feed-orchestrator' AND is_active AND COALESCE(is_snapshot,false)=false AND deleted_at IS NULL;
  IF step->>'action' <> 'complete_workflow' THEN RAISE EXCEPTION '540: complete runs %, not complete_workflow', step->>'action'; END IF;
  IF step->'config' ? 'result_mapping' THEN RAISE EXCEPTION '540: complete ALREADY carries result_mapping'; END IF;
  IF step->'config'->'output_fields' <> '["seed_result","dispatch_result","triage_result","news_render_result","news_commit_result","rss_render_result","rss_commit_result"]'::jsonb THEN RAISE EXCEPTION '540: output_fields changed, re-derive'; END IF;
  IF (SELECT default_config #>> ARRAY['workflow','steps','commit_news','output_field'] FROM agent_definitions WHERE type='content-feed-orchestrator' AND is_active AND COALESCE(is_snapshot,false)=false AND deleted_at IS NULL) <> 'news_commit_result' THEN RAISE EXCEPTION '540: commit_news output_field changed'; END IF;
END $$;
UPDATE agent_definitions SET default_config = jsonb_set(default_config #- '{workflow,steps,complete,config,output_fields}', '{workflow,steps,complete,config,result_mapping}', jsonb_build_object('seed_result','seed_result','dispatch_result','dispatch_result','triage_result','triage_result','news_render_result','news_render_result','news_commit_result','news_commit_result','rss_render_result','rss_render_result','rss_commit_result','rss_commit_result','commit_sha','news_commit_result.response.data.commit_sha'), true), updated_at=NOW() WHERE type='content-feed-orchestrator' AND is_active AND COALESCE(is_snapshot,false)=false AND deleted_at IS NULL;
-- VERIFY (full file): asserts all 8 result_mapping keys exactly, RAISE EXCEPTION (not SELECT) if the mapped path does not resolve against a real orchestration.
